<!-- wp:group {"tagName":"section","align":"full","style":{"spacing":{"padding":{"top":"var:preset|spacing|60","bottom":"var:preset|spacing|60"}}},"backgroundColor":"areia","layout":{"type":"constrained"}} --><section class="wp-block-group alignfull has-areia-background-color has-background" style="padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)"><!-- wp:group {"align":"wide","layout":{"type":"default"}} --><div class="wp-block-group alignwide"><!-- wp:heading {"level":2} --><h2 class="wp-block-heading">Como funciona</h2><!-- /wp:heading --><!-- wp:columns {"align":"wide"} --><div class="wp-block-columns alignwide"><!-- wp:column --><div class="wp-block-column"><!-- wp:group {"className":"rq-card rq-step","layout":{"type":"default"}} --><div class="wp-block-group rq-card rq-step"><!-- wp:html --><img class="rq-step-ico" src="<?php echo esc_url( get_stylesheet_directory_uri() ); ?>/assets/img/iris/aulas.svg" width="64" height="64" alt="" /><!-- /wp:html --><!-- wp:heading {"level":3} --><h3 class="wp-block-heading">1. Aulas gratuitas</h3><!-- /wp:heading --><!-- wp:paragraph --><p>Crianças, jovens e demais alunos treinam tênis de graça no Parque da Cidade – Ayrton Senna da Silva, em Valinhos, com o professor Pedro Stucchi.</p><!-- /wp:paragraph --></div><!-- /wp:group --></div><!-- /wp:column --><!-- wp:column --><div class="wp-block-column"><!-- wp:group {"className":"rq-card rq-step","layout":{"type":"default"}} --><div class="wp-block-group rq-card rq-step"><!-- wp:html --><img class="rq-step-ico" src="<?php echo esc_url( get_stylesheet_directory_uri() ); ?>/assets/img/iris/boletim.svg" width="64" height="64" alt="" /><!-- /wp:html --><!-- wp:heading {"level":3} --><h3 class="wp-block-heading">2. Boletim em dia</h3><!-- /wp:heading --><!-- wp:paragraph --><p>O lema do projeto, nas palavras do professor, é: “quem tem média 7 na escola, ganha raquete”.</p><!-- /wp:paragraph --></div><!-- /wp:group --></div><!-- /wp:column --><!-- wp:column --><div class="wp-block-column"><!-- wp:group {"className":"rq-card rq-step","layout":{"type":"default"}} --><div class="wp-block-group rq-card rq-step"><!-- wp:html --><img class="rq-step-ico" src="<?php echo esc_url( get_stylesheet_directory_uri() ); ?>/assets/img/iris/raquete.svg" width="64" height="64" alt="" /><!-- /wp:html --><!-- wp:heading {"level":3} --><h3 class="wp-block-heading">3. Raquete e alimentação</h3><!-- /wp:heading --><!-- wp:paragraph --><p>Quem ainda não tem boletim também é reconhecido: “a premiação é dada se comer salada”. Assim o projeto une esporte, educação e saúde.</p><!-- /wp:paragraph --></div><!-- /wp:group --></div><!-- /wp:column --></div><!-- /wp:columns --><!-- wp:paragraph {"className":"rq-fontes"} --><p class="rq-fontes">Fonte: entrevista do professor Pedro Stucchi ao TenisBrasil, 20/04/2026.</p><!-- /wp:paragraph --><!-- wp:paragraph {"className":"rq-fontes"} --><p class="rq-fontes">Fontes: <a href="https://tenisbrasil.uol.com.br/raquete-para-todos-conheca-o-trabalho-genial-de-pedro-stucchi.html" rel="noopener">TenisBrasil, 20/04/2026</a>; <a href="https://www.valinhos.sp.gov.br/portal/noticias/0/3/57570/24-horas-de-tenis-do-clt-une-esporte-e-solidariedade-em-grande-evento-em-valinhos" rel="noopener">Prefeitura de Valinhos, abr/2025</a>.</p><!-- /wp:paragraph --></div><!-- /wp:group --></section><!-- /wp:group -->
